#[cfg(feature = "parser")]
use sqlparser::dialect::{GenericDialect, MySqlDialect, PostgreSqlDialect, SQLiteDialect};
#[cfg(feature = "parser")]
use sqlparser::parser::Parser;

#[cfg(feature = "parser")]
struct Fixture {
    id: &'static str,
    dialect: &'static str,
    sql: &'static str,
}

#[cfg(not(feature = "parser"))]
fn main() {
    println!("parser feature disabled");
}

#[cfg(feature = "parser")]
fn main() {
    let fixtures = [
        Fixture { id: "sqlite-select", dialect: "sqlite", sql: "SELECT * FROM users" },
        Fixture { id: "sqlite-explain-query-plan", dialect: "sqlite", sql: "EXPLAIN QUERY PLAN SELECT * FROM users" },
        Fixture { id: "sqlite-cte-select", dialect: "sqlite", sql: "WITH recent AS (SELECT * FROM orders) SELECT * FROM recent" },
        Fixture { id: "sqlite-pragma-assignment", dialect: "sqlite", sql: "PRAGMA journal_mode = WAL" },
        Fixture { id: "mysql-into-outfile", dialect: "mysql", sql: "SELECT * FROM users INTO OUTFILE '/tmp/users.csv'" },
        Fixture { id: "mysql-lock-in-share-mode", dialect: "mysql", sql: "SELECT * FROM users LOCK IN SHARE MODE" },
        Fixture { id: "mysql-versioned-comment", dialect: "mysql", sql: "/*!50000 SELECT * FROM users */" },
        Fixture { id: "postgres-for-no-key-update", dialect: "postgresql", sql: "SELECT * FROM users FOR NO KEY UPDATE" },
        Fixture { id: "postgres-dollar-quoted-semicolon", dialect: "postgresql", sql: "SELECT $tag$semi;colon$tag$" },
        Fixture { id: "sqlite-cte-update", dialect: "sqlite", sql: "WITH stale AS (SELECT id FROM users) UPDATE users SET active = 0" },
        Fixture { id: "generic-select-drop", dialect: "generic", sql: "SELECT 1; DROP TABLE users" },
    ];

    for fixture in fixtures {
        let parsed = match fixture.dialect {
            "sqlite" => Parser::parse_sql(&SQLiteDialect {}, fixture.sql),
            "mysql" => Parser::parse_sql(&MySqlDialect {}, fixture.sql),
            "postgresql" => Parser::parse_sql(&PostgreSqlDialect {}, fixture.sql),
            "generic" => Parser::parse_sql(&GenericDialect {}, fixture.sql),
            _ => unreachable!("fixed fixture dialect"),
        };
        match parsed {
            Ok(statements) => println!("{}\tparsed\t{}\t", fixture.id, statements.len()),
            Err(error) => println!(
                "{}\trejected\t0\t{}",
                fixture.id,
                error
                    .to_string()
                    .replace('\t', " ")
                    .replace('\n', " ")
                    .replace('\r', " ")
            ),
        }
    }
}
